const cafes = window.CAFES;
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved = new Set();
try { const data = JSON.parse(localStorage.getItem('tainan-coffee-saved') || '[]'); if(Array.isArray(data)) saved = new Set(data.filter(id=>cafes.some(c=>c.id===id))); } catch {}
let onlySaved = false;
const query = c => encodeURIComponent(c.name+' '+c.address);
const mapUrl = c => 'https://www.google.com/maps/search/?api=1&query='+query(c);
function setMap(c){ $('#map-title').textContent=c?c.name:'台南咖啡廳地圖'; $('#map').src='https://maps.google.com/maps?q='+(c?query(c):encodeURIComponent('台南 咖啡廳'))+'&output=embed'; }
for(const district of [...new Set(cafes.map(c=>c.district))]){const option=document.createElement('option');option.value=district;option.textContent=district;$('#district').append(option);}
$('#total').textContent=String(cafes.length).padStart(2,'0')+' 間待訪筆記';
function render(){const term=$('#search').value.trim().toLowerCase();const district=$('#district').value;const rows=cafes.filter(c=>(!district||c.district===district)&&(!onlySaved||saved.has(c.id))&&[c.name,c.address,...c.tags].join(' ').toLowerCase().includes(term));$('#count').textContent=`找到 ${rows.length} 間咖啡廳 · 點選店名閱讀筆記`;
$('#cards').innerHTML=rows.length?rows.map(c=>`<article class="card"><div class="card-top"><span class="number">${String(cafes.indexOf(c)+1).padStart(2,'0')} / ${esc(c.district)}</span><button class="save" data-save="${esc(c.id)}" aria-label="收藏 ${esc(c.name)}" aria-pressed="${saved.has(c.id)}">${saved.has(c.id)?'♥':'♡'}</button></div><h3><a href="#cafe/${esc(c.id)}">${esc(c.name)}</a></h3>${c.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<p>${esc(c.summary)}</p><p>⌖ ${esc(c.address)}</p><div class="card-actions"><button class="map-button" data-map="${esc(c.id)}">在地圖上查看 ↗</button><a href="${mapUrl(c)}" target="_blank" rel="noopener noreferrer">Google 地圖 ↗</a><a href="#cafe/${esc(c.id)}">店家筆記 →</a></div></article>`).join(''):'<div class="empty">沒有符合的店家。<br>試試其他關鍵字，或按「重設」。</div>';setMap(rows[0]);}
$('#search').addEventListener('input',render);$('#district').addEventListener('change',render);$('#favorites').addEventListener('click',()=>{onlySaved=!onlySaved;$('#favorites').setAttribute('aria-pressed',onlySaved);render();});$('#reset').addEventListener('click',()=>{$('#search').value='';$('#district').value='';onlySaved=false;$('#favorites').setAttribute('aria-pressed','false');render();});
$('#cards').addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){saved.has(save.dataset.save)?saved.delete(save.dataset.save):saved.add(save.dataset.save);try{localStorage.setItem('tainan-coffee-saved',JSON.stringify([...saved]));}catch{}render();$('#cards').querySelector(`[data-save="${save.dataset.save}"]`)?.focus();}const map=e.target.closest('[data-map]');if(map){setMap(cafes.find(c=>c.id===map.dataset.map));$('.map-panel').scrollIntoView({behavior:'smooth',block:'nearest'});}});
function route(){const isDetail=location.hash.startsWith('#cafe/');$('.hero').hidden=isDetail;$('#explore').hidden=isDetail;$('#detail').hidden=!isDetail;if(!isDetail){document.title='巷裡喝一杯｜台南咖啡廳地圖';return;}const c=cafes.find(c=>c.id===location.hash.slice(6));$('#detail').innerHTML=c?`<a href="#explore">← 返回咖啡地圖</a><p class="eyebrow">COFFEE NOTE / ${esc(c.district)}</p><h1>${esc(c.name)}</h1><p>${esc(c.summary)}</p><p>地址：${esc(c.address)}</p><p>${esc(c.note)}</p><a class="primary" href="${mapUrl(c)}" target="_blank" rel="noopener noreferrer">開啟 Google 地圖 ↗</a><p class="details-meta">來源：<a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">台南旅遊網 ↗</a><br>來源更新：${esc(c.sourceUpdated||'未提供')} ／ 查閱日期：${esc(c.checkedAt)}<br>營業時間、低消、插座、Wi-Fi：未確認，請洽店家。</p>`:'<h2>找不到這篇店家筆記</h2><a href="#explore">返回列表</a>';document.title=c?c.name+'｜巷裡喝一杯':'找不到筆記｜巷裡喝一杯';$('#detail').focus();}
window.addEventListener('hashchange',route);render();route();
